const SYMPTOMS_FR = {
  10: { label: 'Voyant ABS allumé (Calculateur)', category: 'Freinage & ABS', subcategory: 'Calculateur / Bloc hydraulique ABS', description: 'Vérifier le fusible ABS et les broches du connecteur du bloc hydraulique (corrosion ou cosses tordues).' },
  11: { label: 'Voyant ABS fixe (Capteur de roue)', category: 'Freinage & ABS', subcategory: 'Capteur de vitesse de roue ABS', description: 'Inspecter le passage de roue pour détecter un câble de capteur coupé ou de la limaille sur la cible magnétique.' },
  12: { label: 'Pédale de frein très dure', category: 'Freinage & ABS', subcategory: 'Servofrein (Mastervac)', description: 'Contrôler la durite de dépression entre le collecteur d\'admission et le servofrein (fissures ou prise d\'air).' },
  13: { label: 'Voiture tire d\'un côté au freinage', category: 'Freinage & ABS', subcategory: 'Étrier de frein', description: 'Inspecter l\'étrier pour détecter un suintement de liquide autour du piston ou des colonnettes grippées.' },
  14: { label: 'Fuite de liquide de frein', category: 'Freinage & ABS', subcategory: 'Flexible de frein', description: 'Inspecter visuellement les flexibles en caoutchouc (craquelures, hernies) pendant qu\'un assistant appuie sur la pédale.' },
  15: { label: 'Pédale de frein molle (Maître-cylindre)', category: 'Freinage & ABS', subcategory: 'Maître-cylindre de frein', description: 'Vérifier le niveau du bocal de liquide de frein et inspecter l\'arrière du maître-cylindre contre le servofrein.' },
  16: { label: 'Sifflement ou grincement au freinage', category: 'Freinage & ABS', subcategory: 'Plaquettes de frein', description: 'Contrôler l\'épaisseur des garnitures à travers la jante (minimum légal de sécurité : 2 à 3 mm).' },
  17: { label: 'Vibrations dans la pédale au freinage', category: 'Freinage & ABS', subcategory: 'Disques de frein', description: 'Contrôler l\'état de surface du disque (rebord d\'usure, sillons) ou mesurer le voile au comparateur.' },
  18: { label: 'Freinage arrière faible / Pédale longue', category: 'Freinage & ABS', subcategory: 'Mâchoires et tambours de frein', description: 'Déposer le tambour arrière pour contrôler l\'usure des mâchoires et l\'étanchéité des cylindres de roue.' },
  19: { label: 'Pas d\'air froid (Climatisation)', category: 'Climatisation & Chauffage', subcategory: 'Compresseur de climatisation', description: 'Observer la poulie du compresseur avec la clim activée (A/C ON) pour vérifier si l\'embrayage magnétique s\'enclenche.' },
  20: { label: 'Climatisation souffle tiède (Condenseur)', category: 'Climatisation & Chauffage', subcategory: 'Condenseur de climatisation', description: 'Inspecter le condenseur en aluminium derrière la calandre (ailettes pliées, feuilles mortes ou impacts de gravillons).' },
  21: { label: 'Odeur d\'humidité dans la ventilation', category: 'Climatisation & Chauffage', subcategory: 'Évaporateur de climatisation', description: 'Vérifier l\'écoulement d\'eau du tube d\'évacuation sous la voiture et contrôler l\'état du filtre d\'habitacle.' },
  22: { label: 'Manque de froid (Charge gaz clim)', category: 'Climatisation & Chauffage', subcategory: 'Charge de gaz réfrigérant & Pression A/C', description: 'Brancher les manomètres basse et haute pression sur les valves de service pour vérifier la quantité de gaz.' },
  23: { label: 'Débit d\'air faible / Odeur habitacle', category: 'Climatisation & Chauffage', subcategory: 'Filtre d\'habitacle (Filtre à pollen)', description: 'Ouvrir la trappe derrière la boîte à gants et extraire le filtre pour vérifier l\'encrassement (feuilles, poussière noire).' },
  24: { label: 'Plus aucune soufflerie d\'habitacle', category: 'Climatisation & Chauffage', subcategory: 'Pulseur d\'air d\'habitacle', description: 'Écouter le ventilateur sous la boîte à gants passager sur toutes les vitesses de 1 à 4.' },
  25: { label: 'Ventilation ne marche qu\'en vitesse 4', category: 'Climatisation & Chauffage', subcategory: 'Résistance de pulseur d\'air', description: 'Tester la continuité électrique aux bornes du bloc de résistance et vérifier le fusible thermique.' },
  26: { label: 'Surchauffe moteur (Niveau liquide)', category: 'Refroidissement Moteur', subcategory: 'Vase d\'expansion & Niveau de liquide', description: 'Vérifier visuellement le niveau dans le vase d\'expansion à froid et inspecter les fissures ou le joint du bouchon.' },
  27: { label: 'Flaque de liquide de refroidissement sous la voiture', category: 'Refroidissement Moteur', subcategory: 'Détection de fuite de refroidissement', description: 'Mettre le circuit sous pression à 1 bar (15 PSI) avec une pompe manuelle et rechercher les suintements.' },
  28: { label: 'Surchauffe moteur rapide (Thermostat)', category: 'Refroidissement Moteur', subcategory: 'Thermostat moteur (Calorstat)', description: 'Comparer la température des durites supérieure et inférieure du radiateur pendant la montée en température.' },
  29: { label: 'Pas de chauffage dans l\'habitacle', category: 'Refroidissement Moteur', subcategory: 'Radiateur de chauffage d\'habitacle', description: 'Toucher les deux durites d\'entrée et de sortie au tablier : les deux doivent être bien chaudes moteur à 90°C.' },
  30: { label: 'Surchauffe moteur dans les bouchons / à l\'arrêt', category: 'Refroidissement Moteur', subcategory: 'Motoventilateur de radiateur', description: 'Activer la climatisation (A/C) pour vérifier si le ventilateur de radiateur démarre automatiquement et tester son relais.' },
  31: { label: 'Fuite sur durite de refroidissement', category: 'Refroidissement Moteur', subcategory: 'Durites de radiateur et de chauffage', description: 'Presser les durites supérieure et inférieure à froid pour détecter une texture spongieuse, craquelée ou une coupure de collier.' },
  32: { label: 'Surchauffe moteur / Fuite pompe à eau', category: 'Refroidissement Moteur', subcategory: 'Pompe à eau moteur', description: 'Inspecter l\'orifice de purge de la pompe à eau (traces de liquide) et vérifier le jeu du roulement de poulie.' },
  33: { label: 'Ratés d\'allumage / Injecteur encrassé', category: 'Alimentation & Injection', subcategory: 'Injecteurs de carburant', description: 'Utiliser un stéthoscope de mécanicien pour écouter le cliquetis régulier de chaque injecteur au ralenti.' },
  34: { label: 'Moteur cale / Odeur d\'essence (Régulateur)', category: 'Alimentation & Injection', subcategory: 'Régulateur de pression de carburant', description: 'Débrancher la petite durite de dépression du régulateur : si de l\'essence s\'écoule, la membrane interne est percée.' },
  35: { label: 'Trous à l\'accélération à haute vitesse', category: 'Alimentation & Injection', subcategory: 'Pompe à carburant électrique', description: 'Écouter le bourdonnement de 2 secondes sous la banquette arrière à la mise du contact et mesurer la pression de rampe.' },
  36: { label: 'Odeur de carburant dans ou sous le véhicule', category: 'Alimentation & Injection', subcategory: 'Réservoir de carburant & Goulotte', description: 'Inspecter le réservoir, la goulotte de remplissage (corrosion) et le joint caoutchouc du bouchon de réservoir.' },
  37: { label: 'Moteur cale ou hésite en pleine charge', category: 'Alimentation & Injection', subcategory: 'Filtre à carburant', description: 'Vérifier l\'historique d\'entretien (remplacement tous les 40 000 à 60 000 km) et contrôler la restriction de débit.' },
  38: { label: 'Bruit ou décalage de courroie de distribution', category: 'Moteur & Distribution', subcategory: 'Courroie de distribution & Calage', description: 'Écarter le carter supérieur de distribution pour inspecter l\'état des dents, la tension et l\'effilochage de la courroie.' },
  39: { label: 'Couinement strident sous le capot moteur', category: 'Moteur & Distribution', subcategory: 'Courroie d\'accessoires (Serpentine)', description: 'Inspecter les stries de la courroie (micro-fissures, glaçage, effilochage) et contrôler le repère du galet tendeur.' },
  40: { label: 'Perte de puissance / Sifflement turbo', category: 'Moteur & Distribution', subcategory: 'Turbocompresseur & Pression de suralimentation', description: 'Inspecter les durites de suralimentation (fissures, traces d\'huile) et vérifier la commande de géométrie variable / wastegate.' },
  41: { label: 'Démarrage difficile à froid (Diesel)', category: 'Moteur & Distribution', subcategory: 'Bougies de préchauffage Diesel', description: 'Mesurer la résistance électrique de chaque bougie de préchauffage au multimètre (valeur normale : 0,5 à 1,5 ohm).' },
  42: { label: 'À-coups et vibrations moteur (Supports)', category: 'Moteur & Distribution', subcategory: 'Supports moteur et boîte (Silentblocs)', description: 'Inspecter les silentblocs caoutchouc/hydrauliques (déchirures, fuite d\'huile) et le basculement moteur à l\'accélération.' },
  43: { label: 'Fuite d\'huile sur le haut moteur', category: 'Moteur & Distribution', subcategory: 'Joint de couvre-culasse', description: 'Inspecter le plan de joint entre la culasse et le couvre-culasse (suintement d\'huile sur le collecteur d\'échappement).' },
  44: { label: 'Voyant de pression d\'huile rouge allumé', category: 'Moteur & Distribution', subcategory: 'Pompe à huile & Pression de lubrification', description: 'Visser un manomètre mécanique à la place du manocontact pour mesurer la pression réelle au ralenti et à 3000 tr/min.' },
  45: { label: 'Fumée bleue à l\'accélération / Conso d\'huile', category: 'Moteur & Distribution', subcategory: 'Segments de piston & Compression moteur', description: 'Effectuer un test de compression à sec puis avec huile sur tous les cylindres (11-14 bars essence, 25-30 bars diesel).' },
  46: { label: 'Odeur d\'œuf pourri / Soufre à l\'échappement', category: 'Échappement & Antipollution', subcategory: 'Catalyseur (Pot catalytique)', description: 'Mesurer la température d\'entrée et de sortie au thermomètre infrarouge (la sortie doit être 20°C à 50°C plus chaude).' },
  47: { label: 'Voyant moteur allumé (Sonde Lambda P0130-P0167)', category: 'Échappement & Antipollution', subcategory: 'Sonde Lambda (Capteur d\'oxygène O2)', description: 'Lire la tension de la sonde O2 en direct (oscillation entre 0,1V et 0,9V) et mesurer la résistance du circuit de chauffage.' },
  48: { label: 'Voyant moteur EVAP / Calage après plein (P0441)', category: 'Échappement & Antipollution', subcategory: 'Électrovanne de purge Canister (EVAP)', description: 'Débrancher la durite et souffler dans la vanne : hors tension (sans 12V), elle doit être totalement fermée et étanche.' },
  49: { label: 'Cliquetis d\'échappement au démarrage à froid', category: 'Échappement & Antipollution', subcategory: 'Collecteur d\'échappement & Joint', description: 'Inspecter la bride du collecteur sur la culasse avec un miroir (traces de suie noire ou goujons cassés).' },
  50: { label: 'Voyant moteur / Ralenti instable (Capteur MAP)', category: 'Échappement & Antipollution', subcategory: 'Capteur de pression d\'admission (MAP)', description: 'Lire la tension MAP contact mis moteur coupé (~4,8V / 100 kPa atmosphérique) et vérifier sa durite de dépression.' },
  51: { label: 'Le démarreur tourne très lentement', category: 'Électrique & Démarrage', subcategory: 'Batterie 12V & Cosses', description: 'Mesurer la tension batterie au repos au multimètre (12,6V = 100%, 12,0V = déchargée) et vérifier l\'oxydation des bornes.' },
  52: { label: 'Voyant batterie rouge allumé en roulant', category: 'Électrique & Démarrage', subcategory: 'Alternateur & Circuit de charge', description: 'Mesurer la tension aux bornes de la batterie moteur tournant avec phares et dégivrage allumés (doit afficher 13,8V à 14,5V).' },
  53: { label: 'Le moteur ne se lance pas (Clic au démarrage)', category: 'Électrique & Démarrage', subcategory: 'Démarreur & Solénoïde', description: 'Vérifier la présence du signal 12V sur le petit fil d\'excitation du solénoïde lorsque la clé est tournée sur START.' },
  54: { label: 'Ratés moteur sous charge / Temps humide', category: 'Électrique & Démarrage', subcategory: 'Système d\'allumage (Bobines & Faisceau)', description: 'Vaporiser une fine brume d\'eau sur les câbles/bobines dans l\'obscurité moteur au ralenti pour repérer d\'éventuels arcs bleus.' },
  55: { label: 'Vitre électrique bloquée ou ne remonte plus', category: 'Électrique & Démarrage', subcategory: 'Moteur & Mécanisme de lève-vitre', description: 'Écouter dans le panneau de porte en appuyant sur le bouton et tester l\'alimentation 12V au connecteur du moteur.' },
  56: { label: 'Phare avant ne fonctionne plus d\'un côté', category: 'Électrique & Démarrage', subcategory: 'Ampoule de phare & Douille', description: 'Inspecter le filament de l\'ampoule halogène et vérifier que le connecteur en plastique n\'a pas fondu.' },
  57: { label: 'Essuie-glaces ne fonctionnent plus du tout', category: 'Électrique & Démarrage', subcategory: 'Moteur & Tringlerie d\'essuie-glace', description: 'Vérifier le fusible d\'essuie-glace, écouter le moteur sous la baie de pare-brise et contrôler les rotules de tringlerie.' },
  58: { label: 'Pédale d\'embrayage molle ou reste au plancher', category: 'Transmission & Embrayage', subcategory: 'Émetteur & Récepteur d\'embrayage', description: 'Vérifier le niveau de liquide dans le bocal partagé frein/embrayage et inspecter la moquette sous la pédale d\'embrayage.' },
  59: { label: 'Boîte automatique patine ou donne des à-coups', category: 'Transmission & Embrayage', subcategory: 'Boîte de vitesses automatique (Huile ATF & Crépine)', description: 'Contrôler le niveau et la couleur de l\'huile ATF (à 40°C) : elle doit être rouge translucide, non noire ni sentir le brûlé.' },
  60: { label: 'Vibrations sous le plancher entre 80 et 110 km/h', category: 'Transmission & Embrayage', subcategory: 'Arbre de transmission, Cardan & Croisillon', description: 'Saisir l\'arbre de transmission ou le cardan à la main pour contrôler le jeu en rotation des croisillons et l\'état des soufflets.' },
  61: { label: 'Sifflement ou grondement du pont arrière à l\'accélération', category: 'Transmission & Embrayage', subcategory: 'Différentiel & Couple conique', description: 'Vérifier le niveau d\'huile de pont/différentiel et inspecter le bouchon de vidange magnétique (présence de limaille).' },
  62: { label: 'Grondement en tournant le volant (Direction dure)', category: 'Direction Assistée', subcategory: 'Pompe & Liquide de direction assistée', description: 'Vérifier le niveau du bocal de direction assistée et rechercher la présence de mousse ou d\'émulsion moteur tournant.' },
  63: { label: 'Bruit de roulement sourd qui augmente avec la vitesse', category: 'Roues & Pneumatiques', subcategory: 'Roulement de roue & Moyeu', description: 'Lever la roue, saisir le pneu à 12h et 6h et secouer fermement d\'avant en arrière pour détecter un jeu au roulement.' },
  64: { label: 'Voyant de pression des pneus (TPMS) allumé', category: 'Roues & Pneumatiques', subcategory: 'Système de contrôle de pression des pneus (TPMS)', description: 'Vérifier la pression à froid des 4 pneus au manomètre par rapport à l\'étiquette constructeur dans l\'encadrement de portière.' }
};

// Questions 16 à 125 (par ID)
const QUESTIONS_FR = {
  16: { title: 'Vérifier le fusible ABS dans le boîtier moteur', description: 'Repérez le fusible ABS / ESP sur le schéma de la boîte à fusibles et retirez-le avec la pince pour vérifier si le filament métallique est intact.', warning_text: 'Une panne ABS peut bloquer les roues lors d\'un freinage d\'urgence. Conduisez avec prudence.' },
  17: { title: 'Inspecter le faisceau et le connecteur du bloc ABS', description: 'Examinez le connecteur multibroches sur le groupe hydraulique ABS (broches tordues, infiltration d\'eau ou fils dénudés).', warning_text: 'Une panne ABS peut bloquer les roues lors d\'un freinage d\'urgence. Conduisez avec prudence.' },
  18: { title: 'Inspecter les connecteurs des capteurs de roue dans les passages de roue', description: 'Vérifiez le connecteur électrique derrière le pare-boue (clips cassés ou câble sectionné par des projections).', warning_text: 'Évitez les freinages brusques sur chaussée mouillée tant que le voyant ABS est actif.' },
  19: { title: 'Contrôler la tête du capteur et la cible magnétique (limaille ou fissure)', description: 'Examinez l\'extrémité magnétique du capteur et la couronne dentée/magnétique sur le moyeu ou le cardan.', warning_text: 'Évitez les freinages brusques sur chaussée mouillée tant que le voyant ABS est actif.' },
  20: { title: 'Vérifier la durite de dépression du servofrein et le clapet anti-retour', description: 'Inspectez l\'épaisse durite reliant le collecteur d\'admission (ou la pompe à vide) au servofrein (fissures, débranchement).', warning_text: 'Un servofrein défaillant allonge considérablement la distance d\'arrêt. Ne roulez pas sur route ouverte.' },
  21: { title: 'Pomper sur la pédale de frein moteur coupé puis démarrer', description: 'Pompez 5 fois sur la pédale moteur éteint jusqu\'à ce qu\'elle devienne dure, maintenez-la enfoncée et démarrez le moteur.', warning_text: 'Un servofrein défaillant allonge considérablement la distance d\'arrêt. Ne roulez pas sur route ouverte.' },
  22: { title: 'Inspecter le corps de l\'étrier et le cache-poussière du piston', description: 'Regardez à travers la jante ou derrière la roue s\'il y a des traces grasses de liquide de frein autour du piston ou de la vis de purge.', warning_text: 'Un étrier grippé provoque une surchauffe extrême du disque et une ébullition du liquide de frein.' },
  23: { title: 'Vérifier la libre rotation de la roue et le coulissement des colonnettes', description: 'Levez la roue, faites-la tourner à la main, freinez puis relâchez : vérifiez si la roue tourne à nouveau librement sans frotter.', warning_text: 'Un étrier grippé provoque une surchauffe extrême du disque et une ébullition du liquide de frein.' },
  24: { title: 'Inspection visuelle et flexion des flexibles de frein en caoutchouc', description: 'Braquez les roues à fond et pliez légèrement le flexible pour repérer d\'éventuelles craquelures profondes ou suintements.', warning_text: 'La rupture d\'un flexible de frein entraîne une perte immédiate du freinage hydraulique.' },
  25: { title: 'Observer la dilatation du flexible sous forte pression à la pédale', description: 'Demandez à un assistant d\'appuyer fortement sur la pédale de frein pendant que vous observez le flexible.', warning_text: 'La rupture d\'un flexible de frein entraîne une perte immédiate du freinage hydraulique.' },
  26: { title: 'Vérifier le niveau et la couleur du liquide de frein dans le bocal', description: 'Examinez le réservoir translucide côté conducteur : le niveau doit se situer entre MIN et MAX et le liquide doit être clair.', warning_text: 'Une fuite interne du maître-cylindre peut provoquer un enfoncement soudain de la pédale à l\'arrêt.' },
  27: { title: 'Contrôler le maintien de pression en appuyant 30 secondes sur la pédale', description: 'Vérifiez l\'absence de fuite entre le maître-cylindre et le servofrein, puis maintenez une pression constante sur la pédale pendant 30 s.', warning_text: 'Une fuite interne du maître-cylindre peut provoquer un enfoncement soudain de la pédale à l\'arrêt.' },
  28: { title: 'Mesurer l\'épaisseur restante des garnitures de plaquettes', description: 'Éclairez à travers les branches de la jante pour contrôler l\'épaisseur de garniture des plaquettes interne et externe.', warning_text: 'Des plaquettes usées jusqu\'au métal détruisent les disques et doublent la distance de freinage.' },
  29: { title: 'Rechercher un glaçage, des fissures ou une usure asymétrique', description: 'Vérifiez si la plaquette externe est épaisse alors que l\'interne est totalement usée (signe de colonnettes d\'étrier grippées).', warning_text: 'Des plaquettes usées jusqu\'au métal détruisent les disques et doublent la distance de freinage.' },
  30: { title: 'Mesurer l\'épaisseur du disque par rapport à la cote minimale (MIN TH)', description: 'Utilisez un pied à coulisse ou un micromètre en plusieurs points de la piste de friction du disque de frein.', warning_text: 'Un disque trop fin ou fissuré par la chaleur peut se briser lors d\'un freinage d\'urgence.' },
  31: { title: 'Inspecter la surface du disque (sillons, rebord de rouille ou voile)', description: 'Examinez les faces interne et externe pour détecter un bleuissement (surchauffe), des sillons profonds ou un voile.', warning_text: 'Un disque trop fin ou fissuré par la chaleur peut se briser lors d\'un freinage d\'urgence.' },
  32: { title: 'Contrôler l\'épaisseur des garnitures de mâchoires de tambour', description: 'Mesurez l\'épaisseur de friction sur les mâchoires à l\'intérieur du tambour arrière et vérifiez l\'absence de fuite au cylindre de roue.', warning_text: 'Des mâchoires imbibées de liquide de frein ou de graisse ne doivent jamais être réutilisées.' },
  33: { title: 'Inspecter la piste intérieure du tambour (rayures, fissures ou ovalisation)', description: 'Vérifiez l\'intérieur du tambour en fonte pour détecter des stries profondes, des points de chauffe ou une ovalisation.', warning_text: 'Des mâchoires imbibées de liquide de frein ou de graisse ne doivent jamais être réutilisées.' },
  34: { title: 'Observer l\'enclenchement de l\'embrayage du compresseur de clim', description: 'Démarrez le moteur et réglez la clim au maximum de froid (A/C MAX). Observez si le plateau central de la poulie du compresseur tourne.', warning_text: '' },
  35: { title: 'Rechercher des traces de traceur UV vert ou d\'huile sur le compresseur', description: 'Inspectez le joint d\'arbre avant et le carter du compresseur pour repérer un dépôt huileux verdâtre ou de la limaille.', warning_text: '' },
  36: { title: 'Inspecter les ailettes du condenseur (insectes, boue, feuilles)', description: 'Éclairez à travers la grille de pare-chocs avant pour examiner l\'échangeur en aluminium.', warning_text: '' },
  37: { title: 'Rechercher des impacts de gravillons et taches grasses sur le condenseur', description: 'Examinez les coins inférieurs et la face avant pour repérer des taches sombres et grasses là où des gravillons ont percé les tubes.', warning_text: '' },
  38: { title: 'Contrôler l\'encrassement bactérien / moisissures sur l\'évaporateur', description: 'Sentez l\'air pulsé à la mise en route et vérifiez le boîtier d\'évaporateur via la trappe du filtre d\'habitacle.', warning_text: '' },
  39: { title: 'Tester la sonde de température anti-givrage de l\'évaporateur', description: 'Vérifiez si l\'air froid fonctionne pendant 10-15 minutes avant de se couper à cause de la prise en glace de l\'évaporateur.', warning_text: '' },
  40: { title: 'Mesurer les pressions statique et dynamique du gaz réfrigérant', description: 'Branchez le raccord basse pression (port L). La pression au repos normale est de 3,5 à 5,5 bars (50-80 PSI) selon la température ambiante.', warning_text: '' },
  41: { title: 'Contrôler l\'étanchéité des valves Schrader et des raccords', description: 'Pulvérisez de l\'eau savonneuse sur les obus de valves de service et examinez tous les raccords de conduites en aluminium.', warning_text: '' },
  42: { title: 'Inspecter la cartouche du filtre d\'habitacle (filtre à pollen)', description: 'Retirez le filtre d\'habitacle situé derrière la boîte à gants ou sous la baie de pare-brise.', warning_text: '' },
  43: { title: 'Vérifier la grille d\'entrée d\'air sous le pare-brise (feuilles mortes)', description: 'Inspectez la baie en plastique sous les essuie-glaces pour retirer les feuilles mortes et déboucher les évacuations d\'eau de pluie.', warning_text: '' },
  44: { title: 'Tester la réponse électrique du pulseur d\'air sur la vitesse 4', description: 'Mettez la ventilation au maximum (vitesse 4) et vérifiez la présence du 12V sur le connecteur à 2 broches du moteur de soufflerie.', warning_text: '' },
  45: { title: 'Vérifier l\'absence de corps étrangers dans la turbine du pulseur', description: 'Déposez le pulseur (3 vis) et vérifiez si des feuilles, débris ou ailettes cassées bloquent la cage d\'écureuil.', warning_text: '' },
  46: { title: 'Tester la continuité de la résistance de chauffage au multimètre', description: 'Mesurez les valeurs de résistance entre les broches du bloc de résistance ou du module variateur électronique.', warning_text: '' },
  47: { title: 'Inspecter le connecteur électrique (plastique fondu ou broches brûlées)', description: 'Examinez la prise branchée sur le module de résistance pour détecter des cosses noircies ou fondues par échauffement.', warning_text: '' },
  48: { title: 'Vérifier le niveau et la couleur du liquide de refroidissement à froid', description: 'Moteur totalement froid, vérifiez que le niveau se situe entre MIN et MAX et que le liquide est propre (rose, jaune, bleu ou vert).', warning_text: 'N\'ouvrez JAMAIS le bouchon du vase d\'expansion moteur chaud ! Risque de brûlure grave par projection de vapeur bouillante.' },
  49: { title: 'Inspecter les soudures du vase d\'expansion et le joint du bouchon', description: 'Examinez la soudure plastique autour du bocal ainsi que les embouts de durites pour repérer des micro-fissures ou dépôts blanchâtres.', warning_text: 'N\'ouvrez JAMAIS le bouchon du vase d\'expansion moteur chaud ! Risque de brûlure grave par projection de vapeur bouillante.' },
  50: { title: 'Mettre le circuit de refroidissement à froid sous pression (1,0 bar)', description: 'Fixez la pompe d\'épreuve sur le vase d\'expansion, gonflez à 1,0 bar (15 PSI) et observez si l\'aiguille chute en 10 minutes.', warning_text: 'Rouler sans liquide de refroidissement déforme la culasse en aluminium en quelques minutes.' },
  51: { title: 'Localiser précisément le point de fuite de liquide', description: 'Suivez les durites, le boîtier de thermostat, la pompe à eau et les boîtes à eau du radiateur pour repérer les gouttes.', warning_text: 'Rouler sans liquide de refroidissement déforme la culasse en aluminium en quelques minutes.' },
  52: { title: 'Vérifier la propreté du faisceau de radiateur et le passage d\'air', description: 'Assurez-vous que le radiateur moteur n\'est pas obstrué par de la boue, des feuilles ou des débris.', warning_text: 'Un thermostat bloqué fermé empêche toute circulation vers le radiateur, causant une surchauffe immédiate.' },
  53: { title: 'Tester l\'ouverture du thermostat en touchant les durites de radiateur', description: 'Démarrez moteur froid : la durite supérieure doit rester froide jusqu\'à ~88°C-92°C puis devenir brusquement très chaude.', warning_text: 'Un thermostat bloqué fermé empêche toute circulation vers le radiateur, causant une surchauffe immédiate.' },
  54: { title: 'Rechercher des traces d\'humidité sous les tapis passager', description: 'Tâtez la moquette aux pieds du passager près de la console centrale (dépôt gras et sucré de liquide de refroidissement).', warning_text: 'Un radiateur de chauffage percé embue instantanément le pare-brise avec des vapeurs toxiques.' },
  55: { title: 'Comparer la température des deux durites de chauffage au tablier', description: 'Moteur à 90°C avec le chauffage au maximum, touchez prudemment les deux durites qui entrent dans l\'habitacle.', warning_text: 'Un radiateur de chauffage percé embue instantanément le pare-brise avec des vapeurs toxiques.' },
  56: { title: 'Commander la mise en route du ventilateur via la climatisation', description: 'Moteur au ralenti, enclenchez la climatisation (A/C ON) : cela doit activer immédiatement la petite vitesse du motoventilateur.', warning_text: 'Le ventilateur électrique peut démarrer tout seul même contact coupé. Gardez les mains éloignées des pales.' },
  57: { title: 'Contrôler le relais de motoventilateur et sa résistance', description: 'Repérez le relais de ventilateur dans la boîte à fusibles moteur et testez-le en l\'échangeant avec un relais identique.', warning_text: 'Le ventilateur électrique peut démarrer tout seul même contact coupé. Gardez les mains éloignées des pales.' },
  58: { title: 'Presser les durites à froid pour évaluer l\'état du caoutchouc', description: 'Vérifiez sur toute la longueur des durites supérieure et inférieure l\'absence de gonflement, de ramollissement par l\'huile ou de craquelures.', warning_text: 'L\'éclatement d\'une durite de radiateur vide instantanément tout le circuit sur le moteur brûlant.' },
  59: { title: 'Inspecter les colliers et manchons de raccordement (croûtes de liquide)', description: 'Examinez les extrémités des durites sur le radiateur et le boîtier d\'eau pour repérer des dépôts cristallins blancs ou roses.', warning_text: 'L\'éclatement d\'une durite de radiateur vide instantanément tout le circuit sur le moteur brûlant.' },
  60: { title: 'Inspecter l\'orifice de décharge de la pompe à eau (traces de fuite)', description: 'Utilisez un miroir d\'inspection et une lampe pour regarder sous l\'axe de la poulie de pompe à eau.', warning_text: 'Si la pompe à eau est entraînée par la distribution, son grippage peut rompre la courroie et casser le moteur.' },
  61: { title: 'Vérifier le retour de liquide dans le bocal et le jeu de la poulie', description: 'Contrôlez l\'absence de jeu sur la poulie de pompe à eau et vérifiez que le petit jet de retour coule bien dans le vase d\'expansion à 2500 tr/min.', warning_text: 'Si la pompe à eau est entraînée par la distribution, son grippage peut rompre la courroie et casser le moteur.' },
  62: { title: 'Contrôler la pulvérisation et l\'équilibrage des injecteurs', description: 'Écoutez le cliquetis régulier de chaque injecteur au stéthoscope ou vérifiez les débits de retour / corrections d\'injection à la valise OBD.', warning_text: 'Un injecteur bloqué ouvert peut laver le film d\'huile du cylindre ou bloquer hydrauliquement le moteur.' },
  63: { title: 'Mesurer la résistance électrique de la bobine d\'injecteur au multimètre', description: 'Débranchez le connecteur de l\'injecteur et mesurez la résistance entre ses 2 broches (norme : 12-16 ohms haute impédance).', warning_text: 'Un injecteur bloqué ouvert peut laver le film d\'huile du cylindre ou bloquer hydrauliquement le moteur.' },
  64: { title: 'Vérifier l\'absence d\'essence dans la durite de dépression du régulateur', description: 'Moteur coupé, débranchez le petit tuyau à dépression du régulateur de pression et vérifiez s\'il contient du carburant liquide.', warning_text: 'Une membrane de régulateur percée aspire de l\'essence pure directement dans l\'admission.' },
  65: { title: 'Mesurer la pression de rampe d\'injection sur la valve de test', description: 'Branchez un manomètre de pression de carburant sur la rampe : contact mis, vérifiez la pression constructeur (env. 3,0 à 3,5 bars).', warning_text: 'Une membrane de régulateur percée aspire de l\'essence pure directement dans l\'admission.' },
  66: { title: 'Contrôler la pression et le débit de la pompe de gavage', description: 'Reliez un manomètre sur l\'arrivée de carburant pour lire la pression d\'amorçage et le débit (minimum 1 litre par minute).', warning_text: 'Ne testez jamais le câblage d\'une pompe à carburant près de vapeurs d\'essence. Débranchez la batterie.' },
  67: { title: 'Inspecter la platine de pompe et son connecteur sous la banquette arrière', description: 'Soulevez l\'assise arrière, ouvrez la trappe de visite ronde et vérifiez l\'absence de broches fondues ou de fuite sur la bague.', warning_text: 'Ne testez jamais le câblage d\'une pompe à carburant près de vapeurs d\'essence. Débranchez la batterie.' },
  68: { title: 'Inspecter la coque du réservoir, les sangles et la goulotte de remplissage', description: 'Examinez sous le véhicule les sangles de maintien, le tube de remplissage derrière le pare-boue arrière et le fond du réservoir.', warning_text: 'Toute fuite de carburant liquide sous le véhicule représente un risque d\'incendie extrême.' },
  69: { title: 'Contrôler le joint torique en caoutchouc du bouchon de réservoir', description: 'Dévissez le bouchon de carburant et inspectez son joint en caoutchouc (craquelures, écrasement) et le clic de serrage.', warning_text: 'Toute fuite de carburant liquide sous le véhicule représente un risque d\'incendie extrême.' },
  70: { title: 'Vérifier l\'échéance de remplacement et le colmatage du filtre à carburant', description: 'Localisez le filtre à carburant (sous la caisse ou dans le compartiment moteur sur Diesel) et vérifiez la date du dernier remplacement.', warning_text: '' },
  71: { title: 'Vérifier les raccords rapides et le sens de la flèche de circulation', description: 'Assurez-vous que la flèche gravée sur le filtre pointe bien vers le moteur et que les raccords rapides sont bien verrouillés.', warning_text: '' },
  72: { title: 'Inspecter les dents et le dos de la courroie de distribution (fissures ou huile)', description: 'Déclipsez le cache supérieur de distribution et examinez l\'état des dents en caoutchouc, l\'effilochage ou toute trace d\'huile.', warning_text: 'Sur un moteur interférentiel, la rupture de la courroie de distribution provoque le choc pistons/soupapes et détruit le moteur.' },
  73: { title: 'Contrôler l\'alignement des repères de calage vilebrequin / arbre à cames', description: 'Tournez le moteur à la main au Point Mort Haut (PMH) cylindre 1 et vérifiez que les repères de poulies sont parfaitement alignés.', warning_text: 'Sur un moteur interférentiel, la rupture de la courroie de distribution provoque le choc pistons/soupapes et détruit le moteur.' },
  74: { title: 'Inspecter les stries de la courroie d\'accessoires (craquelures et glaçage)', description: 'Examinez la face striée de la courroie à la lampe torche : plus de 3 fissures par centimètre indique une usure avancée.', warning_text: 'La rupture de la courroie d\'accessoires coupe instantanément l\'alternateur, la direction assistée et parfois la pompe à eau.' },
  75: { title: 'Vérifier le galet tendeur automatique et l\'alignement des poulies', description: 'Observez le bras du galet tendeur moteur au ralenti : il doit rester stable sans battements brusques ni grincements.', warning_text: 'La rupture de la courroie d\'accessoires coupe instantanément l\'alternateur, la direction assistée et parfois la pompe à eau.' },
  76: { title: 'Comparer la pression de suralimentation mesurée à la consigne OBD', description: 'Lisez la pression MAP à la valise OBD lors d\'une franche accélération en 3ème vitesse pour détecter un manque de pression (P0299).', warning_text: 'La casse de la turbine du turbocompresseur peut projeter des débris métalliques dans l\'admission moteur.' },
  77: { title: 'Inspecter l\'échangeur d\'air (Intercooler) et les durites de turbo', description: 'Examinez le bas de l\'intercooler et les grosses durites caoutchouc/silicone pour repérer une fissure ou un suintement d\'huile.', warning_text: 'La casse de la turbine du turbocompresseur peut projeter des débris métalliques dans l\'admission moteur.' },
  78: { title: 'Mesurer la résistance individuelle de chaque bougie de préchauffage', description: 'Débranchez la rampe d\'alimentation, placez la pointe noire du multimètre sur la culasse et la rouge sur la tête de chaque bougie.', warning_text: 'Les bougies de préchauffage peuvent gripper et casser dans la culasse. Appliquez toujours du dégrippant moteur tiède.' },
  79: { title: 'Examiner le crayon des bougies (calamine, gonflement ou fusion)', description: 'Vérifiez si l\'extrémité de la bougie déposée est recouverte de suie épaisse, boursouflée ou fondue par un injecteur qui goutte.', warning_text: 'Les bougies de préchauffage peuvent gripper et casser dans la culasse. Appliquez toujours du dégrippant moteur tiède.' },
  80: { title: 'Inspecter le caoutchouc des supports moteur et le Silentbloc anti-couple', description: 'Examinez le support moteur supérieur droit (hydraulique) et la biellette anti-couple inférieure (caoutchouc déchiré ou huile noire).', warning_text: 'Un support moteur rompu laisse le bloc basculer fortement, tirant sur les durites, le faisceau et la ligne d\'échappement.' },
  81: { title: 'Vérifier le serrage des vis de fixation des supports moteur et berceau', description: 'Contrôlez à la clé que tous les boulons de fixation sur le bloc moteur et le châssis sont parfaitement serrés.', warning_text: 'Un support moteur rompu laisse le bloc basculer fortement, tirant sur les durites, le faisceau et la ligne d\'échappement.' },
  82: { title: 'Inspecter le pourtour du couvre-culasse et les puits de bougies', description: 'Sortez les bobines d\'allumage : si leurs embouts caoutchouc baignent dans l\'huile moteur, les joints de puits de bougies fuient.', warning_text: 'L\'huile qui goutte sur le collecteur d\'échappement brûlant dégage une fumée âcre et crée un risque d\'incendie.' },
  83: { title: 'Vérifier le serrage uniforme des vis du couvre-culasse', description: 'Contrôlez que les vis de 10 mm du couvre-culasse sont serrées uniformément (couple habituel : 8 à 10 Nm) et que le plastique n\'est pas fendu.', warning_text: 'L\'huile qui goutte sur le collecteur d\'échappement brûlant dégage une fumée âcre et crée un risque d\'incendie.' },
  84: { title: 'Mesurer la pression d\'huile réelle avec un manomètre mécanique', description: 'Déposez le manocontact de pression d\'huile et vissez un manomètre d\'atelier : minimum 1,0 bar au ralenti à chaud et 3,5 bars à 3000 tr/min.', warning_text: 'COUPEZ LE MOTEUR IMMÉDIATEMENT si le voyant d\'huile rouge s\'allume ! Tourner sans pression d\'huile détruit les coussinets de bielle en quelques secondes.' },
  85: { title: 'Contrôler le clapet de décharge de la pompe à huile et la crépine', description: 'Vérifiez que la crépine d\'aspiration dans le carter inférieur n\'est pas bouchée par de la boue d\'huile (sludge) et que le clapet n\'est pas grippé.', warning_text: 'COUPEZ LE MOTEUR IMMÉDIATEMENT si le voyant d\'huile rouge s\'allume ! Tourner sans pression d\'huile détruit les coussinets de bielle en quelques secondes.' },
  86: { title: 'Effectuer un test de compression des cylindres à sec puis à l\'huile', description: 'Déposez les bougies, coupez l\'injection et vissez le compressiomètre sur chaque cylindre en actionnant le démarreur sur 5 compressions.', warning_text: 'Des segments racleurs usés brûlent l\'huile moteur, ce qui encrasse et détruit le catalyseur et les bougies.' },
  87: { title: 'Vérifier la pression de souffle au carter (Blow-by) au bouchon d\'huile', description: 'Moteur chaud au ralenti, dévissez le bouchon de remplissage d\'huile et posez-le sans le verrouiller : vérifiez s\'il saute violemment sous la pression des gaz.', warning_text: 'Des segments racleurs usés brûlent l\'huile moteur, ce qui encrasse et détruit le catalyseur et les bougies.' },
  88: { title: 'Tapoter le corps du catalyseur pour détecter un monolithe céramique cassé', description: 'Frappez doucement l\'enveloppe du catalyseur froid avec un maillet caoutchouc pour écouter si le nid d\'abeille interne sonne le grelot.', warning_text: 'Un catalyseur bouché crée une contre-pression d\'échappement énorme provoquant surchauffe moteur et perte totale de puissance.' },
  89: { title: 'Comparer les signaux des sondes Lambda amont et aval (P0420)', description: 'Lisez les courbes OBD : la sonde amont doit osciller rapidement (0,1V à 0,9V) tandis que la sonde aval doit rester stable (~0,45V à 0,7V).', warning_text: 'Un catalyseur bouché crée une contre-pression d\'échappement énorme provoquant surchauffe moteur et perte totale de puissance.' },
  90: { title: 'Contrôler la fréquence d\'oscillation de la sonde Lambda amont', description: 'Observez la tension de la sonde O2 au scanner OBD au ralenti à chaud : elle doit basculer nettement entre 0,1V (pauvre) et 0,9V (riche) chaque seconde.', warning_text: 'Une sonde lambda défaillante fausse l\'injection, fait surconsommer (+20%) et encrasse le catalyseur.' },
  91: { title: 'Inspecter le faisceau de la sonde et mesurer la résistance de chauffage', description: 'Vérifiez que la gaine électrique n\'a pas fondu contre l\'échappement et mesurez la résistance entre les 2 fils blancs de chauffage (4 à 15 ohms).', warning_text: 'Une sonde lambda défaillante fausse l\'injection, fait surconsommer (+20%) et encrasse le catalyseur.' },
  92: { title: 'Tester l\'étanchéité au repos de l\'électrovanne de purge Canister', description: 'Déposez l\'électrovanne EVAP et soufflez dans l\'embout : non alimentée électriquement, aucun air ne doit pouvoir passer.', warning_text: '' },
  93: { title: 'Inspecter les conduites de vapeurs d\'essence du réservoir au moteur', description: 'Vérifiez l\'état des tuyaux en nylon et caoutchouc reliant le filtre à charbon actif (canister) au collecteur d\'admission.', warning_text: '' },
  94: { title: 'Rechercher des fissures et des traînées de suie noire sur le collecteur', description: 'Examinez le collecteur d\'échappement en fonte ou inox entre les conduits des cylindres pour repérer des fissures thermiques ou de la suie.', warning_text: 'Les gaz d\'échappement contiennent du monoxyde de carbone (CO) inodore pouvant pénétrer dans l\'habitacle par la ventilation.' },
  95: { title: 'Vérifier l\'absence de goujons de collecteur cassés dans la culasse', description: 'Inspectez chaque goujon de fixation sur la culasse : les goujons des extrémités cassent souvent à ras sous l\'effet de la dilatation thermique.', warning_text: 'Les gaz d\'échappement contiennent du monoxyde de carbone (CO) inodore pouvant pénétrer dans l\'habitacle par la ventilation.' },
  96: { title: 'Mesurer la tension d\'alimentation (5V) et le signal du capteur MAP', description: 'Vérifiez au multimètre ou à la valise OBD que le signal passe d\'environ 4,5V contact mis à ~1,2V au ralenti sous dépression.', warning_text: '' },
  97: { title: 'Inspecter la durite de dépression ou le joint torique du capteur MAP', description: 'Vérifiez la petite durite caoutchouc ou le joint torique d\'étanchéité du capteur sur la tubulure d\'admission en plastique.', warning_text: '' },
  98: { title: 'Mesurer la tension de la batterie au repos et pendant le coup de démarreur', description: 'Moteur coupé, placez le multimètre sur les bornes : 12,6V = chargée à 100%. Au coup de démarreur, la tension ne doit pas chuter sous 9,6V.', warning_text: 'Les batteries dégagent de l\'hydrogène explosif. Évitez toute étincelle ou flamme à proximité.' },
  99: { title: 'Vérifier l\'oxydation (sulfate blanc/bleu) et le serrage des cosses', description: 'Saisissez les cosses de batterie à la main et essayez de les faire pivoter : elles doivent être parfaitement bloquées et propres.', warning_text: 'Les batteries dégagent de l\'hydrogène explosif. Évitez toute étincelle ou flamme à proximité.' },
  100: { title: 'Mesurer la tension de charge de l\'alternateur sous charge électrique', description: 'Démarrez le moteur, allumez les pleins phares et le dégivrage arrière, puis mesurez la tension aux bornes de la batterie au multimètre.', warning_text: 'Si l\'alternateur lâche en roulant, le moteur calera dès que la batterie sera vide, coupant l\'assistance de direction et de freinage.' },
  101: { title: 'Vérifier le patinement de la courroie et la poulie roue-libre d\'alternateur', description: 'Contrôlez la tension de la courroie d\'accessoires et vérifiez que la poulie débrayable de l\'alternateur n\'est pas grippée.', warning_text: 'Si l\'alternateur lâche en roulant, le moteur calera dès que la batterie sera vide, coupant l\'assistance de direction et de freinage.' },
  102: { title: 'Tester l\'arrivée du signal 12V d\'excitation sur la borne 50 du solénoïde', description: 'Branchez une lampe témoin ou un multimètre sur le petit fil de commande du démarreur pendant qu\'un assistant tourne la clé sur START.', warning_text: 'Assurez-vous que la boîte est au point mort (ou Park) avec le frein à main serré avant d\'intervenir sur le démarreur.' },
  103: { title: 'Évaluer l\'état des charbons internes et du lanceur (Bendix) du démarreur', description: 'Notez si le démarreur tourne dans le vide avec un sifflement aigu (lanceur roue-libre HS) ou s\'il ne consomme aucun courant (charbons usés).', warning_text: 'Assurez-vous que la boîte est au point mort (ou Park) avec le frein à main serré avant d\'intervenir sur le démarreur.' },
  104: { title: 'Inspecter les bobines et capuchons de bougies (amorçages ou fissures)', description: 'Examinez les prolongateurs caoutchouc des bobines crayon pour repérer des traces grises d\'arc électrique (carbon tracking) ou des craquelures.', warning_text: 'La haute tension d\'allumage atteint 25 000 à 45 000 volts. Ne touchez jamais les câbles moteur tournant.' },
  105: { title: 'Mesurer la résistance des câbles HT ou des enroulements de bobine', description: 'Mesurez au multimètre la résistance de chaque câble d\'allumage d\'un bout à l\'autre (environ 3 000 à 7 000 ohms par pied).', warning_text: 'La haute tension d\'allumage atteint 25 000 à 45 000 volts. Ne touchez jamais les câbles moteur tournant.' },
  106: { title: 'Tester l\'alimentation 12V et l\'inversion de polarité à la prise du moteur de vitre', description: 'Dégarnissez le panneau de porte, débranchez la prise à 2 broches du moteur et testez la tension en actionnant le bouton montée/descente.', warning_text: '' },
  107: { title: 'Inspecter le tambour d\'enroulement du câble et les agrafes de guidage', description: 'Vérifiez à l\'intérieur de la portière si le câble en acier est emmêlé/effiloché ou si les patins en plastique qui portent la vitre sont cassés.', warning_text: '' },
  108: { title: 'Déposer l\'ampoule de phare et examiner le filament à la lumière', description: 'Retirez le cache étanche, déclipsez l\'agrafe ressort et sortez l\'ampoule H7/H4 pour vérifier si le filament est coupé ou le verre noirci.', warning_text: 'Ne touchez JAMAIS le verre d\'une ampoule halogène ou xénon avec les doigts : le sébum fait éclater l\'ampoule à chaud.' },
  109: { title: 'Inspecter la douille en plastique et le serrage des cosses électriques', description: 'Regardez à l\'intérieur du connecteur de l\'ampoule pour détecter du plastique fondu, du vert-de-gris ou des cosses lâches.', warning_text: 'Ne touchez JAMAIS le verre d\'une ampoule halogène ou xénon avec les doigts : le sébum fait éclater l\'ampoule à chaud.' },
  110: { title: 'Vérifier la présence du 12V sur le connecteur du moteur d\'essuie-glace', description: 'Activez le commodo d\'essuie-glace en petite et grande vitesse et testez l\'arrivée de courant sur la prise du moteur au multimètre.', warning_text: 'Conduire sous la pluie avec des essuie-glaces en panne annule toute visibilité.' },
  111: { title: 'Inspecter les rotules de tringlerie et les axes de pivots d\'essuie-glace', description: 'Retirez la grille d\'auvent sous le pare-brise et vérifiez si une biellette de tringlerie s\'est déboîtée ou si un axe est grippé par la rouille.', warning_text: 'Conduire sous la pluie avec des essuie-glaces en panne annule toute visibilité.' },
  112: { title: 'Inspecter la tige de poussée de l\'émetteur au-dessus de la pédale d\'embrayage', description: 'Regardez sous le tableau de bord côté conducteur, là où la tige de la pédale entre dans l\'émetteur, pour détecter un suintement de liquide.', warning_text: 'Une perte de pression hydraulique d\'embrayage empêche de passer les vitesses ou de débrayer.' },
  113: { title: 'Inspecter le récepteur d\'embrayage sur la cloche de boîte de vitesses', description: 'Examinez le soufflet caoutchouc du cylindre récepteur externe (ou le trou d\'évacuation sous la cloche de boîte pour une butée hydraulique CSC).', warning_text: 'Une perte de pression hydraulique d\'embrayage empêche de passer les vitesses ou de débrayer.' },
  114: { title: 'Contrôler le niveau et la couleur de l\'huile de boîte automatique (ATF)', description: 'Moteur chaud tournant sur Park (P), tirez la jauge ATF (ou vérifiez le bouchon de niveau à 35°C-45°C) et essuyez sur un papier blanc.', warning_text: 'Rouler avec un niveau d\'huile ATF trop bas brûle les disques d\'embrayage internes et le convertisseur de couple.' },
  115: { title: 'Inspecter le joint de carter de boîte et la limaille sur l\'aimant', description: 'Vérifiez l\'absence de fuite autour du carter inférieur de boîte et l\'état de la crépine interne / aimant de décantation.', warning_text: 'Rouler avec un niveau d\'huile ATF trop bas brûle les disques d\'embrayage internes et le convertisseur de couple.' },
  116: { title: 'Contrôler le jeu des croisillons d\'arbre et l\'état des soufflets de cardan', description: 'Inspectez les soufflets caoutchouc (déchirure, projection de graisse) et tournez l\'arbre à la main en sens inverse pour sentir un jeu radial.', warning_text: 'La rupture d\'un croisillon d\'arbre de transmission à haute vitesse peut décrocher l\'arbre sur la chaussée.' },
  117: { title: 'Inspecter le palier central en caoutchouc et l\'équilibrage de l\'arbre', description: 'Examinez la membrane caoutchouc du palier relais central (déchirure) et vérifiez qu\'aucune masselotte d\'équilibrage ne s\'est dessoudée.', warning_text: 'La rupture d\'un croisillon d\'arbre de transmission à haute vitesse peut décrocher l\'arbre sur la chaussée.' },
  118: { title: 'Vérifier le niveau d\'huile de pont et rechercher des paillettes métalliques', description: 'Dévissez le bouchon de remplissage du différentiel : l\'huile doit affleurer le bord inférieur de l\'orifice et ne pas contenir de paillettes argentées.', warning_text: 'Un pont arrière tournant sans huile finit par se souder et bloquer les roues motrices.' },
  119: { title: 'Contrôler le jeu du roulement de pignon d\'attaque et l\'entre-dents', description: 'Secouez la tulipe d\'entrée du pont de haut en bas à la main pour détecter un jeu anormal dans les roulements coniques.', warning_text: 'Un pont arrière tournant sans huile finit par se souder et bloquer les roues motrices.' },
  120: { title: 'Vérifier le niveau de liquide de direction assistée et la présence de mousse', description: 'Moteur au ralenti, braquez de butée à butée deux fois puis vérifiez le niveau (COLD/HOT) et l\'absence d\'émulsion mousseuse dans le bocal.', warning_text: 'Une perte soudaine d\'assistance de direction rend le volant extrêmement dur en virage ou en manœuvre.' },
  121: { title: 'Inspecter les durites haute pression et les soufflets de crémaillère', description: 'Examinez les raccords sertis des flexibles haute pression et pressez les soufflets de crémaillère de direction pour détecter une fuite d\'huile.', warning_text: 'Une perte soudaine d\'assistance de direction rend le volant extrêmement dur en virage ou en manœuvre.' },
  122: { title: 'Secouer la roue levée en plaçant les mains à 12h et 6h', description: 'Roue levée sur chandelle, saisissez le pneu en haut (12h) et en bas (6h) et tirez/poussez fermement pour sentir un claquement ou un jeu.', warning_text: 'Un roulement de roue en fin de vie peut se bloquer net ou provoquer le détachement du moyeu à grande vitesse.' },
  123: { title: 'Lancer la roue à la main en touchant le ressort d\'amortisseur', description: 'Faites tourner rapidement la roue levée tout en posant les doigts sur une spire du ressort de suspension pour sentir une vibration rugueuse.', warning_text: 'Un roulement de roue en fin de vie peut se bloquer net ou provoquer le détachement du moyeu à grande vitesse.' },
  124: { title: 'Mesurer la pression à froid des 4 pneus avec un manomètre précis', description: 'Relevez la pression de chaque pneu à froid et comparez-la aux valeurs en bars préconisées sur l\'étiquette de portière conducteur.', warning_text: 'Un pneu sous-gonflé chauffe excessivement sur autoroute et risque l\'éclatement.' },
  125: { title: 'Contrôler l\'émission radio et l\'état de la pile des capteurs TPMS', description: 'Interrogez les valves électroniques avec un outil TPMS pour lire l\'état de leur pile lithium interne (durée de vie moyenne : 7 à 10 ans).', warning_text: 'Un pneu sous-gonflé chauffe excessivement sur autoroute et risque l\'éclatement.' }
};

